// 1. Pointer Basics & Array Decay (C/C++)
int value = 42;
int array[3] = {1, 2, 3};

int* p = &value;
int* arr_p = array; // Array name decays to address of first element

*p = 10;            // Dereference: change value

// Accessing array elements
int x = array[1];
int y = *(arr_p + 1); // Pointer arithmetic
int z = arr_p[1];     // Pointer indexing

// 2. Dynamic Allocation (C style: malloc/free)
int N = 5;
// Allocate block of memory for 5 integers
int* buffer = (int*)malloc(N * sizeof(int));

if (buffer == NULL) { /* Handle error */ }

for (int i = 0; i < N; ++i) {
    buffer[i] = i * 2;
}

free(buffer);
// 'buffer' now points to freed memory (dangling)

// 3. Dynamic Allocation (C++ style: new/delete)
int size = 10;

// Allocate array
double* data_arr = new double[size];

// Allocate single object
long* single_obj = new long(99L);

data_arr[0] = 1.0;

delete[] data_arr;    // Must use delete[] for arrays
delete single_obj;    // Must use delete for single objects
